window.RP_SESSION={"id":"S-7ef1f73c6379","messages":[{"id":"RP-II-0133770","time":"2026-08-03T15:53:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"짹짹짹~\n\n개굴개굴개굴\n\n우어어어어ㅓㅓ어어어어ㅓ어어어어어ㅓ어엉","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133771","time":"2026-08-03T15:53:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"음 지금은 평화로운 길드의 점심","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133772","time":"2026-08-03T15:53:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 매번 이 시간에 눈을 뜨곤 합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133773","time":"2026-08-03T15:54:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가끔가다 아침에 일어날땐 아마도 의뢰중, 그런 상황이 아니라면 대부분 점심까지 달달한 잠을 만끽하곤 해요.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133774","time":"2026-08-03T15:55:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이날도 여느때처럼 늘정을 부리며 간신히 일어난 허그는, 기지개를 켜고, 밥을 먹으러 갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133775","time":"2026-08-03T15:55:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"길드에 처음 들어왔을때만 하더라도, 길드 밥은 한 번을 안먹었었는데 말이죠.\n이젠 수프나 빵도 그럭저럭 먹을 만 해서, 2~3일에 한 번씩은 들르는 것 같습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133776","time":"2026-08-03T15:56:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아흐~~ 오늘도 열심히 먹고, 열심히 나가서, 열심히 돈 값 해보자고. 여이!“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133777","time":"2026-08-03T15:56:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"우적우적","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133778","time":"2026-08-03T15:57:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"우적우적","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133779","time":"2026-08-03T15:58:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"음, 길드가 망하려 그러나… 오늘 수프엔 고기가 없네요.\n어쩔 수 없이 허그는 자신의 시크릿 미라클 황천의 주머니에서 육포를 두어개 꺼낸 뒤, 대충 찢어 수프에 담가먹습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133780","time":"2026-08-03T15:58:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이 안에 얼마만큼의 육포가 아직 남아있을지는 허그만 알겠죠.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133781","time":"2026-08-03T15:59:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어후, 그럭저럭 괜찮았네.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133782","time":"2026-08-03T15:59:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 식사를 마치고, 뭐 이것저것 한 뒤, 다시 자신의 방으로 올라갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133783","time":"2026-08-03T16:00:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"곳에서 준비물을 챙기고, 무기를 닦고, 주머니에 육포를 더 욱여넣은 뒤, 오늘도 사냥을 떠나요.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133784","time":"2026-08-03T16:00:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133785","time":"2026-08-03T16:00:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133786","time":"2026-08-03T16:01:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이곳은 ‘벼언두울희우의 마을’,\n서쪽과 골기아 사이 어딘가에 대충 끼어 지어졌으며, 다들 흔히 생각하는 그런 시골 마을입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133787","time":"2026-08-03T16:01:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”흐흐흥~ 어? 여이~“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133788","time":"2026-08-03T16:02:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 마을 입구에 들어서자, 자신을 기다리고  있는 누군가를 발견합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133789","time":"2026-08-03T16:02:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"의뢰인…일까요?","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133790","time":"2026-08-03T16:02:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!운명-5","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133791","time":"2026-08-03T16:02:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 1 - 5 = -4\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0133792","time":"2026-08-03T16:02:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…? 가만 보니 이 사내, 뭔가 이상합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133793","time":"2026-08-03T16:03:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아까부터 어수룩하게 자꾸 발만 동동 구르면서, 허그와 눈을 잘 못마주치는군요.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133794","time":"2026-08-03T16:03:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…여이… 설마…“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133795","time":"2026-08-03T16:03:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”“아마 그 설마가 맞을텐데요…”“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133796","time":"2026-08-03T16:03:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”끄아… 제발… 내가 여기까지 어떻게 왔는데.“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133797","time":"2026-08-03T16:03:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”“그, 이런말씀 드려서 죄송하지만…”“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133798","time":"2026-08-03T16:04:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 더 말 안해도 알아. 의뢰인이 토꼈구만.“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133799","time":"2026-08-03T16:05:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이런! 가끔가다 이런 때가 있죠.\n의뢰를 부탁했으나 어느 순간 갑작스레 상황이 자연스레 해결되던, 아니면 막상 부르고 보니 돈을 내기가 부담스럽던, 무슨 이유에서든 간에 의뢰를 중간에 관두는 사람들은 많습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133800","time":"2026-08-03T16:06:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"의뢰 중단을 알리고 싶어도, 이미 수주자가 출발을 한 경우도 있고 말이죠.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133801","time":"2026-08-03T16:07:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그래도 그사람 대신 기다려줘서 고맙구만. 뭐 오래간만에 산책 좀 하다 돌아간다고 쯤 생각해둘테니까, 그리 미안해하진 마.\n네가 잘못한게 아니고, 그녀석이랑 내가 뭐가 안맞은거였겠지, 끄후…“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133802","time":"2026-08-03T16:08:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”“아… 넵! 감사합니다! 그럼 전 이만, 볼 일이 있어서요…!”“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133803","time":"2026-08-03T16:08:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 그쪽도 좋은 하루 되라고~“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133804","time":"2026-08-03T16:08:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…그리 하여 어수룩한 사내는 마을 안쪽으로 떠나갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133805","time":"2026-08-03T16:09:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…에헤이, 뭐 하면서 놀고있는담.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133806","time":"2026-08-03T16:09:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133807","time":"2026-08-03T16:09:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-II-0133808","time":"2026-08-03T16:13:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아 참, 의뢰지는 아직 길드에 붙어있어 다른 불쌍한 누군가도 이곳에 도착할 수도 있겠네요~","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133809","time":"2026-08-03T16:13:00+09:00","room":"RP II","name":"가델랏 허그 / 마을의 전달자","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0133810","time":"2026-08-03T16:13:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
